/**
 * Parses a valid TCP/UDP port number from a string.
 */
export function parsePort(input: string): number | undefined {
  const port = Number.parseInt(input.trim(), 10);

  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    return undefined;
  }

  return port;
}
