/**
 * Parses a TCP port number from a string or number and returns undefined when the value is invalid.
 */
export function parsePort(value: string | number): number | undefined {
  const port = typeof value === "number" ? value : Number.parseInt(value, 10);

  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    return undefined;
  }

  return port;
}
