/**
 * Parses a TCP port value and returns a valid integer port number.
 */
export function parsePort(value: string | number | undefined, fallback = 3000): number {
  const port = typeof value === "number" ? value : Number.parseInt(value ?? "", 10);
  return Number.isInteger(port) && port >= 0 && port <= 65535 ? port : fallback;
}
